"""Public hand support search; no lexical outcomes and no heldout seed access."""
import hashlib,json,re
from collections import defaultdict
from pathlib import Path
from vs import corpus,ivtff

HERE=Path(__file__).resolve().parent

def count(page,paragraph=True):
    return sum(not ivtff.uncertain(w) for l in page.lines if not paragraph or l.unit=='P' for w in l.words)

def main():
    inventories={}
    for edition in ('zl','it','rf'):
        rows=[]
        for p in corpus.pages(edition):
            if p.hand not in ('3','5'):continue
            rows.append(dict(id=p.id,hand=p.hand,section=p.section,currier=p.language,
                             bifolio=p.meta.get('Q','?')+':'+p.meta.get('B','?'),
                             certain_P=count(p),certain_all=count(p,False)))
        inventories[edition]=rows
    primary={p.id:p for p in corpus.pages('zl')};it={p.id:p for p in corpus.pages('it')}
    common=[]
    train_ids={p.id for p in corpus.split_pages('practice','zl')[0]}
    for pid,p in primary.items():
        q=it.get(pid)
        if not q or (p.hand,p.section,p.language)!=(q.hand,q.section,q.language):continue
        if p.hand not in ('2','3','5'):continue
        common.append(dict(id=pid,hand=p.hand,section=p.section,currier=p.language,
                           bifolio=p.meta.get('Q','?')+':'+p.meta.get('B','?'),
                           minimum_P=min(count(p),count(q)),training=pid in train_ids))
    sensitivities={}
    for floor in (1,20,40):
        for name,condition in [('herbal_B',lambda x:x['section']=='H' and x['currier']=='B'),
                               ('herbal_B_or_unknown',lambda x:x['section']=='H' and x['currier'] in ('B',None)),
                               ('all_sections_B',lambda x:x['currier']=='B'),('all_sections_any',lambda x:True)]:
            rows=[x for x in common if x['minimum_P']>=floor and condition(x)]
            groups={h:sorted({x['bifolio'] for x in rows if x['hand']==h}) for h in ('2','3','5')}
            train={h:sorted({x['bifolio'] for x in rows if x['hand']==h and x['training']}) for h in ('2','3','5')}
            remaining={h:{b:len(set(train[h])-{b}) for b in groups[h]} for h in groups}
            sensitivities[f'{name}/{floor}']=dict(bifolia=groups,training_bifolia=train,
                                                train_count_after_own_bifolio_exclusion=remaining)
    table={}
    for hand in ('3','5'):
        table[hand]={}
        for b in sorted({x['bifolio'] for x in inventories['zl'] if x['hand']==hand}):
            rows=[x for x in inventories['zl'] if x['hand']==hand and x['bifolio']==b]
            table[hand][b]=dict(pages=[x['id'] for x in rows],sections=sorted({x['section'] for x in rows}),
                                currier=sorted({str(x['currier']) for x in rows}),
                                certain_P=sum(x['certain_P'] for x in rows))
    assert set(table['5'])=={'F:1','H:1'}
    assert len(table['3'])==8
    result=dict(plan=json.loads((HERE/'plan.json').read_text()),all_transcription_inventories=inventories,
                zl_physical_table=table,sensitivity=sensitivities,
                source_notes={'davis2022_pp5_6':'Figure2 and surrounding text place hand5 in botanical quires6/8 and hand3 on ff58/65, the inner quire17 bifolio and the surviving quire20 bifolia. These are corroborating annotations, not independent manuscripts.',
                'metadata_discrepancy':'ZL/IT/RF annotate f58r/v Currier A despite the source generalization that hands3/4/5 use B; f65r/v lack Currier. No labels are altered to enlarge the H/B sample.',
                'mixed_page':'Davis describes f115r as hand2 lines1–12 and hand3 thereafter. Page-level metadata is hand2; assigning the hand3 portion adds no physical bifolio because T:2 already contains hand3 f104r/v and f115v.',
                'source_internal_caveat':'Davis2022 p7 calls f66v one of only three hand5 pages, while p5 explicitly also places hand5 in quire6. The complete inventory is based on the pinned page labels and p5/6 physical description; the isolated p7 count is not used.'},
                sources=['https://ceur-ws.org/Vol-3313/keynote2.pdf','https://manuscriptroadtrip.wordpress.com/2025/01/19/voynich-codicology/'],
                transcription_sha256={corpus.TRANSLITERATIONS[e]:hashlib.sha256(Path('data/raw',corpus.TRANSLITERATIONS[e]).read_bytes()).hexdigest() for e in ('zl','it','rf')},
                sha256={n:hashlib.sha256((HERE/n).read_bytes()).hexdigest() for n in ('plan.json','inventory.py','davis2022.pdf')})
    (HERE/'result.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(table,indent=2))

if __name__=='__main__':main()
